from dataclasses import dataclass
import json
from pathlib import Path
import struct

import numpy as np
from PIL import Image, ImageOps

from character_data import card
from character_model import MODEL56, downsample_roi, inference_scores, winner

HEADER = struct.Struct("<4sIBBiI")


@dataclass
class Frame:
    pixels: np.ndarray
    wire_id: int
    status: int
    score: int
    sequence: int = 0
    cycles: int = 0


class Twin:
    def __init__(self, model=MODEL56):
        with np.load(model / "integer_model.npz", allow_pickle=False) as f:
            self.model = {k: f[k] for k in f.files}
        self.names = [
            c["name"] for c in json.loads((model / "classes.json").read_text("utf8"))
        ]
        channels = 3
        for i, width in enumerate((12, 24, 40, 48)):
            w = self.model[f"w{i}"]
            if (
                w.shape != (width, channels, 3, 3)
                or self.model[f"b{i}"].shape != (width,)
            ):
                raise ValueError(f"第 {i+1} 层卷积参数尺寸不匹配")
            channels = width
        if (
            len(self.names) != 15
            or self.model["shifts"].shape != (4,)
            or self.model["wf"].shape != (15, channels * 9)
            or self.model["bf"].shape != (15,)
        ):
            raise ValueError("需要 56×56 单视图、15 类角色的整数模型")
        self.side = 56

    def classify(self, pixels):
        if pixels.shape != (self.side, self.side):
            raise ValueError(f"当前模型需要 {self.side} × {self.side} RGB565 输入")
        scores = inference_scores(pixels, self.model)
        label, score = winner(scores)
        return Frame(pixels, label, 1, score), scores

    def describe(self, frame):
        if frame.status == 2:
            return "推理超时"
        return f"{frame.wire_id + 1:02d}  {self.names[frame.wire_id]}"


class PacketParser:
    def __init__(self, side=56):
        if side != 56:
            raise ValueError("NPU4 frames use 56x56 RGB565 pixels")
        self.side = side
        self.magic = b"NPU4"
        self.check_offset = HEADER.size + 2 * side * side
        self.packet_size = self.check_offset + 4
        self.buffer = bytearray()
        self.rejected = 0

    def feed(self, data):
        self.buffer.extend(data)
        frames = []
        while self.buffer:
            offset = self.buffer.find(self.magic)
            if offset < 0:

                keep = next(
                    (n for n in (3, 2, 1) if self.buffer.endswith(self.magic[:n])), 0
                )
                del self.buffer[: len(self.buffer) - keep]
                break
            del self.buffer[:offset]
            if len(self.buffer) < self.packet_size:
                break
            _, seq, wire_id, status, score, cycles = HEADER.unpack_from(self.buffer)
            (check,) = struct.unpack_from("<I", self.buffer, self.check_offset)
            if (
                check != sum(self.buffer[: self.check_offset])
                or status not in (1, 2)
                or not (wire_id < 15 if status == 1 else wire_id == 15)
            ):
                self.rejected += 1
                del self.buffer[0]
                continue
            raw = bytes(self.buffer[HEADER.size : self.check_offset])
            pixels = np.frombuffer(raw, "<u2").reshape(self.side, self.side)
            frames.append(Frame(pixels, wire_id, status, score, seq, cycles))
            del self.buffer[: self.packet_size]
        return frames


def optical_roi(image):
    qvga = ImageOps.fit(
        image.convert("RGB"), (320, 240), method=Image.Resampling.LANCZOS
    )
    return np.asarray(qvga.crop((48, 8, 272, 232)))


def input_pixels(path, mode, side=56):
    if mode == "raw" or path.suffix.lower() == ".rgb565":
        raw = path.read_bytes()
        if len(raw) != 2 * side * side:
            raise ValueError(f"当前模型的 RGB565 文件应为 {2*side*side} 字节（小端序）")
        return np.frombuffer(raw, "<u2").reshape(side, side)
    if mode == "frame":
        with Image.open(path) as image:
            return downsample_roi(optical_roi(ImageOps.exif_transpose(image)), side)
    return downsample_roi(card(path), side)


def replay(path, side=56):
    decoder = PacketParser(side)
    frames = decoder.feed(path.read_bytes())
    if not frames or decoder.buffer or decoder.rejected:
        raise ValueError(
            f"{decoder.magic.decode()} 回放不完整或校验失败（完整帧 {len(frames)}，损坏 {decoder.rejected}）"
        )
    return frames


def as_result(twin, frame, scores):
    return dict(
        result=twin.describe(frame),
        wire_id=frame.wire_id,
        status=frame.status,
        max_score=frame.score,
        scores=[int(v) for v in scores],
    )
